from produire import produire,paras,steps,table
from medicaments import ketotifene
parts=[
('La {conjonctivite allergique} est une inflammation de la conjonctive liée à une réponse à un allergène. Le prurit est souvent au premier plan. Les formes saisonnières et perannuelles simples doivent être distinguées des formes sévères avec atteinte cornéenne.',paras('La leçon traite surtout des formes habituelles liées aux pollens ou allergènes persistants. Les kératoconjonctivites vernales ou atopiques et les réactions aux produits locaux demandent parfois une prise en charge spécialisée.', 'Un prurit isolé n’est pas un test diagnostique absolu. Douleur profonde, photophobie importante ou baisse visuelle imposent de rechercher une autre atteinte ou une complication.')),
('Le {terrain atopique oriente sans être indispensable}. Rhinite et exposition à un allergène peuvent accompagner les symptômes. Une atteinte bilatérale est fréquente.',paras('La forme saisonnière suit notamment l’exposition aux pollens. La forme perannuelle peut être liée à des allergènes présents toute l’année, tels que les acariens.', 'Les estimations de fréquence varient selon définition et population ; aucune proportion étrangère n’est présentée ici comme mesure suisse. Demander le retentissement sur sommeil, études, travail et port de lentilles.')),
('Le {mécanisme implique médiateurs et surface oculaire}. Une réaction d’hypersensibilité peut activer les mastocytes et libérer de l’histamine. Elle provoque prurit, rougeur, larmoiement et parfois chémosis.',paras('Le chémosis est un œdème conjonctival. L’altération du film lacrymal peut contribuer à une sécheresse et à une sensation de sable.', 'Les antihistaminiques locaux ciblent une part de la réaction. Le soulagement ne prouve pas l’absence d’une autre maladie et ne dispense pas de vérifier la cornée si les signes sont atypiques.')),
('Le {tri recherche les signes incompatibles avec une forme simple}. Douleur importante, photophobie ou baisse visuelle exige une évaluation rapide. Un porteur de lentilles ne doit pas être classé allergique sans examen.',paras('Une atteinte cornéenne dans une forme allergique sévère peut menacer la vision. Kératite infectieuse et uvéite restent des diagnostics différentiels importants.', 'Antécédent opératoire, immunosuppression, sécrétion hyperpurulente ou atteinte générale abaissent le seuil d’orientation. Ne pas prolonger un essai antihistaminique devant une alarme.')),
('L’{anamnèse relie symptômes et exposition}. Rechercher prurit, saisonnalité, rhinite et antécédents atopiques. Préciser produits cosmétiques, collyres et lentilles.',paras('Demander si les symptômes diminuent loin de l’exposition et s’ils reviennent au même moment de l’année. Une exposition professionnelle ou domestique peut être en cause.', 'Rechercher douleur, baisse visuelle, sécrétions, contage et symptômes unilatéraux persistants. Un conservateur ou un collyre peut lui-même entretenir l’irritation ; ne pas augmenter les instillations sans réévaluation.')),
('L’{examen vérifie vision et surface oculaire}. Comparer les yeux et inspecter paupières, conjonctive et cornée. La présence de chémosis peut soutenir l’hypothèse sans la confirmer seule.',paras('Les sécrétions sont souvent aqueuses ou séromuqueuses. Les papilles conjonctivales peuvent être observées à l’examen spécialisé, mais ne sont pas exclusives d’une allergie.', 'Documenter l’acuité visuelle et rechercher atteinte cornéenne si photophobie ou gêne inhabituelle. Les formes sévères ou persistantes nécessitent l’examen à la lampe à fente.')),
('L’{approche syndromique sépare allergie et autres causes}. L’association prurit, bilatéralité et exposition est utile. Les signes d’infection ou d’atteinte profonde restent prioritaires.',table(['Tableau','Orientation'],[['Prurit, larmoiement, rhinite et exposition.','Allergie probable après examen.'],['Contage et début successif des deux yeux.','Conjonctivite virale possible.'],['Croûtes des paupières, gêne chronique.','Blépharite ou sécheresse associée.'],['Douleur, photophobie, baisse visuelle.','Complication cornéenne ou autre urgence.'],['Symptômes après un nouveau produit.','Irritation ou allergie de contact à discuter.']])) ,
('Le {diagnostic est surtout clinique}. Il repose sur le tableau et sa relation à l’exposition. Une allergie connue n’explique pas automatiquement tout œil rouge ultérieur.',paras('La distinction saisonnière et perannuelle aide à organiser la prévention. Les formes vernales ou atopiques sévères ne sont pas de simples allergies saisonnières prolongées.', 'Une amélioration sous antihistaminique peut soutenir l’hypothèse sans la prouver. Une douleur ou une baisse visuelle persistante exige une réévaluation indépendante de cette réponse.')),
('Les {examens complémentaires sont sélectifs}. Une forme simple ne demande pas systématiquement de bilan allergologique. Le spécialiste décide les investigations selon sévérité, doute et retentissement.',paras('Des tests allergologiques peuvent aider lorsque l’allergène reste incertain ou qu’une stratégie plus large est envisagée. Ils ne remplacent pas l’examen oculaire.', 'La lampe à fente recherche lésions cornéennes et formes sévères. Une culture n’est pas un examen de routine de l’allergie, mais peut être pertinente si une infection est suspectée.')),
('L’{algorithme associe éviction et traitement ciblé}. Évaluer d’abord la sécurité visuelle. Adapter ensuite les soins à la forme et à la spécialité choisie.',steps('Rechercher douleur, photophobie, baisse visuelle et lentilles.', 'Si alarme ou forme sévère, orienter vers l’ophtalmologue.', 'Si forme simple, identifier exposition, proposer compresses fraîches et mesures d’éviction.', 'Choisir un traitement local dans son indication, avec vérification d’âge et de durée.', 'Réévaluer les symptômes persistants et la tolérance des produits.')),
('La {prise en charge suisse privilégie les mesures locales adaptées}. Éviction réaliste de l’allergène, compresses fraîches et lubrification peuvent aider. Un collyre antiallergique est choisi selon son indication précise.',paras('Le kétotifène décrit ci-dessous concerne la conjonctivite saisonnière selon la notice de cette spécialité. La recommandation de classe pour les allergies perannuelles ne suffit pas à élargir automatiquement son autorisation.', '@@MEDICAMENTS@@', 'Une rhinite associée peut justifier une prise en charge complémentaire. Les antihistaminiques oraux ne sont pas une substitution automatique au traitement local et leur tolérance doit être évaluée.', 'Les corticoïdes topiques et les immunomodulateurs utilisés dans les formes sévères relèvent du spécialiste. Ne pas reprendre un ancien flacon de corticoïde sans examen, notamment si infection ou atteinte cornéenne possible.')),
('La {prévention et le suivi} portent sur l’exposition et la tolérance. Éviter de frotter les yeux et de contaminer les embouts. La durée du traitement reste celle de la spécialité et de la prescription.',paras('Une préparation sans conservateur peut être utile selon fréquence, surface oculaire et tolérance. Les lentilles sont suspendues sur un œil inflammatoire ; un délai de remise indiqué dans une notice n’annule pas cette précaution clinique.', 'Réévaluer en cas de persistance malgré mesures adaptées, besoin prolongé de traitement ou aggravation. Toute baisse visuelle, douleur importante ou photophobie nouvelle impose un avis plus rapide.')),
('Le {point clé} est le prurit dans son contexte, avec vision et cornée vérifiées. Une allergie simple n’entraîne pas normalement une menace visuelle. Les formes sévères et les diagnostics concurrents ne doivent pas être masqués par un traitement symptomatique.',paras('Préserver la distinction entre recommandation de classe et indication de spécialité. Pour Zaditen Ophtha, âge minimal de trois ans et durée maximale de six semaines restent les repères suisses cités.'))]
quiz=[('Quel symptôme est souvent dominant ?','Le prurit.'),('Une allergie connue explique-t-elle tout œil rouge ?','Non.'),('Quelle différence entre saisonnière et perannuelle ?','Le rythme et la persistance de l’exposition allergénique.'),('La bilatéralité suffit-elle au diagnostic ?','Non.'),('Qu’est-ce que le chémosis ?','Un œdème conjonctival.'),('Une douleur profonde est-elle typique d’une forme simple ?','Non, rechercher une autre cause ou complication.'),('Une baisse visuelle peut-elle attendre l’effet du collyre ?','Non.'),('Peut-on attribuer sans examen un œil rouge aux seules lentilles ?','Non, rechercher notamment une kératite et obtenir une évaluation adaptée.'),('Les tests allergologiques sont-ils systématiques ?','Non.'),('Quel âge minimal indique Zaditen Ophtha ?','Trois ans.'),('Quelle durée maximale indique cette notice ?','Six semaines.'),('Cette indication couvre-t-elle automatiquement toute allergie perannuelle ?','Non, la notice vise la forme saisonnière.'),('Un corticoïde ancien peut-il être repris librement ?','Non.'),('Le soulagement sous antihistaminique exclut-il une autre maladie ?','Non.')]
produire(3,parts,quiz,(1,3,5,12),ketotifene)
